package com.lolfm.champion;
import static org.assertj.core.api.Assertions.*;import com.fasterxml.jackson.databind.ObjectMapper;import com.lolfm.simulator.*;import org.junit.jupiter.api.Test;
class ChampionPowerProfileCatalogTest{final ChampionCatalog c=new ChampionCatalog(new ObjectMapper());final ChampionPowerProfileCatalog p=new ChampionPowerProfileCatalog(new ObjectMapper(),c);
 @Test void catalogIsExactImmutableAndVersionLinked(){assertThat(p.profileVersion()).isEqualTo("initial-30-power-v1");assertThat(p.requiredChampionPoolVersion()).isEqualTo(c.championPoolVersion());assertThat(p.all()).hasSize(30);assertThat(p.all()).extracting(x->x.championId()).containsExactlyInAnyOrderElementsOf(c.all().stream().map(ChampionDefinition::id).toList());assertThatThrownBy(()->p.all().clear()).isInstanceOf(UnsupportedOperationException.class);assertThatThrownBy(()->p.get(new ChampionId("renekton")).contextModifiers().clear()).isInstanceOf(UnsupportedOperationException.class);}
 @Test void allCurvesAndContextsAreComplete(){assertThat(p.levelCurves()).hasSize(8);assertThat(p.itemCurves()).hasSize(8).allSatisfy((k,v)->assertThat(v).hasSize(7));assertThat(p.all()).allSatisfy(x->{assertThat(x.contextModifiers()).hasSize(9);assertThat(x.tags()).isNotEmpty();});}
 @Test void pinnedMappingsAreExact(){assertThat(p.get(new ChampionId("renekton")).levelCurveId()).isEqualTo("EARLY_DOMINANT");assertThat(p.get(new ChampionId("jinx")).itemCurveId()).isEqualTo("HYPER_CARRY");assertThat(p.get(new ChampionId("leblanc")).contextModifiers().get(ProgressionCombatContext.ROAM)).isEqualTo(.26);assertThat(p.get(new ChampionId("viktor")).contextModifiers().get(ProgressionCombatContext.TEAMFIGHT)).isEqualTo(.18);}
}
